import unittest
from typing import List


def concatenate(strings: List[str]) -> str:
    return ''.join(strings)


# Unit test for function concatenate
def test_concatenate():
    assert concatenate([]) == ''
    assert concatenate(['x']) == 'x'
    assert concatenate(['a', 'b', 'c']) == 'abc'
    assert concatenate(['hello', ' ', 'world']) == 'hello world'
    assert concatenate(['', '', '']) == ''
    assert concatenate(['a', '', 'b']) == 'ab'
    print("All tests passed!")


class TestConcatenate(unittest.TestCase):
    def test_empty_list(self):
        self.assertEqual(concatenate([]), '')

    def test_single_element(self):
        self.assertEqual(concatenate(['x']), 'x')

    def test_multiple_elements(self):
        self.assertEqual(concatenate(['a', 'b', 'c']), 'abc')

    def test_with_spaces(self):
        self.assertEqual(concatenate(['hello', ' ', 'world']), 'hello world')

    def test_all_empty_strings(self):
        self.assertEqual(concatenate(['', '', '']), '')

    def test_mixed_empty(self):
        self.assertEqual(concatenate(['a', '', 'b']), 'ab')


if __name__ == '__main__':
    test_concatenate()
    unittest.main()
